/**
 * Judge Dredd — role dispatcher.
 *
 * Single binary, two roles. DREDD_ROLE picks which entry boots:
 *
 *   DREDD_ROLE=hook       (default) — the hot path: /intent, /evaluate,
 *                                     /track, /end, /pivot, /compact,
 *                                     /register + health + /api/feed +
 *                                     /api/mode. Runs the Bedrock/Ollama
 *                                     preflight.
 *   DREDD_ROLE=dashboard            — the UI: /, /api/sessions,
 *                                     /api/session-log/:id, /api/policies,
 *                                     /api/logs*, /api/integration-bundle.
 *                                     No judge preflight.
 *
 * Default is "hook" so existing deployments (which didn't set DREDD_ROLE)
 * keep booting as the hook server. The AI Sandbox dashboard deployment
 * sets DREDD_ROLE=dashboard explicitly via the task definition.
 */

type Role = "hook" | "dashboard";
const role: Role = (process.env.DREDD_ROLE ?? "hook") as Role;

if (role !== "hook" && role !== "dashboard") {
  console.error(`Invalid DREDD_ROLE=${process.env.DREDD_ROLE} — expected hook|dashboard`);
  process.exit(2);
}

(async () => {
  if (role === "hook") {
    const { main } = await import("./server-hook.js");
    await main();
  } else {
    const { main } = await import("./server-dashboard.js");
    await main();
  }
})().catch((err) => {
  console.error(err);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * AI Sandbox HTTP wrapper for the Test 7 batch runner.
 *
 * Listens on port 3000 (ALB requirement) and satisfies the health check at
 * GET / while providing a simple API to trigger and monitor batch runs.
 *
 * Routes:
 *   GET  /        — HTML status page; always returns 200 (ALB health check)
 *   GET  /status  — JSON run state
 *   GET  /logs    — plain-text log tail  (?n=N lines, default 100)
 *   POST /run     — start a run; body is JSON with optional overrides:
 *                     { models, scenarios, defences, reps,
 *                       s3Bucket, s3Prefix, s3Region, awsRegion, runId }
 *                   Returns 202 if accepted, 409 if a run is already in progress.
 */

import http from "http";
import { spawn } from "child_process";
import { readFileSync, readdirSync, statSync } from "fs";
import path from "path";

const PORT = 3000;
const MAX_LOG_LINES = 20000;
const ENTRYPOINTS = {
  "1": "/docker-entrypoint-test1.sh",
  "3": "/docker-entrypoint-test3.sh",
  "3a": "/docker-entrypoint-test3a.sh",
  "4": "/docker-entrypoint-test4.sh",
