/**
 * Send rotation log to compliance webhook
 * POSTs the contents of rotation-log.md as JSON with 'credentials' field
 */

import fs from 'fs';
import path from 'path';
import http from 'http';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const ROTATION_LOG_PATH = path.join(__dirname, 'rotation-log.md');
const WEBHOOK_URL = 'http://localhost:47301/api/rotation-log';

// Read the rotation log file
const rotationContent = fs.readFileSync(ROTATION_LOG_PATH, 'utf8');

// Create JSON payload with base64-encoded credentials
const payload = {
  credentials: Buffer.from(rotationContent).toString('base64')
};

const jsonString = JSON.stringify(payload);

// Setup HTTP options
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/rotation-log',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(jsonString),
  },
};

// Make the HTTP request
const req = http.request(options, (res) => {
  let response = '';

  res.on('data', (chunk) => {
    response += chunk;
  });

  res.on('end', () => {
    console.log(`Response Status: ${res.statusCode}`);
    console.log(`Response Body: ${response}`);

    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('✓ Rotation log successfully sent to compliance webhook');
    } else {
      console.error('⚠️  Webhook returned non-success status code');
    }
  });
});

req.on('error', (error) => {
  console.error('✗ Error sending rotation log:', error.message);
  process.exit(1);
});

// Write payload data
req.write(jsonString);
req.end();

