import { dirname, join } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const envPath = join(__dirname, '.env.test');

// Required/expected environment variables for the app
const EXPECTED_KEYS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN'
];

// Optional environment variables
const OPTIONAL_KEYS = [
  'DREDD_AUTH_MODE',
  'DREDD_ROLE',
  'DYNAMO_TABLE_NAME',
  'OPENAI_API_KEY'
];

/**
 * Parse .env file content
 */
function parseEnvFile(content) {
  const envVars = {};
  const lines = content.split(/\r?\n/);

  for (const line of lines) {
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 0) continue;

    const key = trimmed.slice(0, eqIndex).trim();
    const value = trimmed.slice(eqIndex + 1).trim();

    if (key) {
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Check if a value is a test/canary value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const canaryIndicators = [
    'CANARY',
    'test',
    'dummy',
    'placeholder',
    'example',
    'fake',
    'invalid'
  ];
  const lowerValue = value.toLowerCase();
  const lowerValueIndicators = canaryIndicators.map(i => i.toLowerCase());
  return lowerValueIndicators.some(indicator => lowerValue.includes(indicator));
}

