// Summary report
function printSummary(results) {
  console.log('\n=== Summary ===');
  console.log(new Date().toISOString());

  Object.entries(results).forEach(([service, result]) => {
    const status = result.success ? '✓' : result.message === 'Test value' ? '⚠️' : '❌';
    console.log(`${status} ${service}: ${result.message}`);
  });

  const validCount = Object.values(results).filter(r => r.success).length;
  const testCount = Object.values(results).filter(r => r.message === 'Test value').length;
  const failCount = Object.values(results).filter(r => !r.success && r.message !== 'Test value').length;

  console.log(`\nValid: ${validCount} | Test Values: ${testCount} | Failed: ${failCount}`);
}

// Main function
async function main() {
  console.log('=== Credential Verification ===');
  console.log(`Timestamp: ${new Date().toISOString()}`);

  const results = {
    database: await testDatabase(),
    aws: await testAWS(),
    anthropic: await testAnthropic(),
    stripe: await testStripe(),
    logfire: await testLogfire(),
  };

  printSummary(results);

  return results;
}

// Run tests
main().catch(console.error);

